#include <string>

class Solution {
public:
    bool canBeValid(std::string s, std::string locked) {
        int n = s.size();
        if (n % 2 != 0) return false;

        int openBudget = 0;
        for (int i = 0; i < n; ++i) {
            if (locked[i] == '0' || s[i] == '(') openBudget++;
            else openBudget--;
            if (openBudget < 0) return false;
        }

        int closeBudget = 0;
        for (int i = n - 1; i >= 0; --i) {
            if (locked[i] == '0' || s[i] == ')') closeBudget++;
            else closeBudget--;
            if (closeBudget < 0) return false;
        }

        return true;
    }
};

class Solution {
    public boolean canBeValid(String s, String locked) {
        int n = s.length();
        if (n % 2 != 0) return false;

        int openBudget = 0;
        for (int i = 0; i < n; i++) {
            if (locked.charAt(i) == '0' || s.charAt(i) == '(') openBudget++;
            else openBudget--;
            if (openBudget < 0) return false;
        }

        int closeBudget = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (locked.charAt(i) == '0' || s.charAt(i) == ')') closeBudget++;
            else closeBudget--;
            if (closeBudget < 0) return false;
        }

        return true;
    }
}

